import{_ as a,o as n,c as i,a2 as t}from"./chunks/framework.CAKCj7G0.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"Java/Spring/Bean.md","filePath":"Java/Spring/Bean.md","lastUpdated":1760888831000}'),o={name:"Java/Spring/Bean.md"};function r(s,e,l,B,p,c){return n(),i("div",null,[...e[0]||(e[0]=[t('<h3 id="_46-4-beanbean" tabindex="-1">46.4. BeanBean <a class="header-anchor" href="#_46-4-beanbean" aria-label="Permalink to &quot;46.4. BeanBean&quot;">​</a></h3><ul><li>生命周期：定义、初始化、生存、销毁</li><li>Bean 生命周期步骤： <ol><li>Spring 启动时进行 Bean 的实例化</li><li>将 Bean 的引用注入到对应 Bean 的属性中</li><li>Bean 实现了 BeanNameAware 接口的情况下，将 Bean 的 Id 传递给 setBeanName 方法</li><li>Bean 实现了 BeanFactoryAware 接口的情况下，调用 setBeanFactory 方法，将 BeanFactory 容器实例传染</li><li>Bean 实现了 ApplicationContextAware 接口的情况下，调用 setApplicationContext 方法，将 bean 所在应用上下文传入</li><li>Bean 实现了 BeanPostProcessor 接口，调用 Spring就将调用他们的postProcessBeforeInitialization 方法</li><li>Bean 实现了 InitializingBean 接口，调用 afterPropertiesSet 方法，如果 Bean 使用 init-method 声明了初始化方法，该方法会被调用（PostConstruct 注解，同样功能）</li><li>如果 Bean 实现了 BeanPostProcessor 接口，调用 postProcessAfterInitialization 方法</li><li>Bean 初始化结束，可以被使用</li><li>Bean 实现了 DisposableBean 接口，销毁时调用 destory 接口，如果 Bean 使用了 destory-method 声明销毁方法,该方法也会被调用（@PreDestroy 注解，同样功能）</li></ol></li><li>作用域（Bean 在 Spring 中默认为单例）： 可以通过 @Scope 注解修改 Bean 的作用域 singleton（Spring 中仅存在一个，单例） prototype（调用 getBean() 时，都会执行 new 操作，返回一个新的实例） request（每次 HTTP 请求都会创建一个新的 Bean） session（同一个 HTTP Session 共享一个 Bean） globalSession（同一个全局 Session 共享一个 Bean）</li></ul>',2)])])}const S=a(o,[["render",r]]);export{d as __pageData,S as default};
